#include <charconv>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <new>
#include <sstream>
#include <string>
#include <string_view>
#include <vector>

long g_allocs = 0;
void* operator new(std::size_t n) {
    ++g_allocs;
    if (void* p = std::malloc(n)) {
        return p;
    }
    throw std::bad_alloc{};
}
void operator delete(void* p) noexcept { std::free(p); }

struct Tick {
    int64_t ts_ns;                 // nanoseconds since midnight
    int64_t bid_ticks, ask_ticks;  // prices in ticks of $0.01
    int64_t bid_sz, ask_sz;        // sizes in shares
};

// Parses one integer, then skips the spaces and newlines after it.
bool next(std::string_view& in, int64_t& out) {
    auto [end, ec] = std::from_chars(in.data(), in.data() + in.size(), out);
    if (ec != std::errc{}) {
        return false;
    }
    in.remove_prefix(end - in.data());
    while (!in.empty() && (in.front() == ' ' || in.front() == '\n')) {
        in.remove_prefix(1);
    }
    return true;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::ostringstream all;
    all << std::cin.rdbuf();  // the whole input in one read
    const std::string text = all.str();
    std::string_view in = text;
    int64_t n = 0;
    next(in, n);

    const long before = g_allocs;
    std::vector<Tick> ticks;
    ticks.reserve(n);
    int rejected = 0;
    Tick t{};
    while (next(in, t.ts_ns) && next(in, t.bid_ticks) && next(in, t.ask_ticks) &&
           next(in, t.bid_sz) && next(in, t.ask_sz)) {
        if (t.bid_ticks >= t.ask_ticks || t.bid_sz <= 0 || t.ask_sz <= 0) {
            ++rejected;  // crossed, locked, or empty: bad data, not a trade signal
            continue;
        }
        ticks.push_back(t);
    }
    const long reserved = g_allocs - before;

    std::vector<Tick> grown;  // the same ticks without reserve, for comparison
    const long start = g_allocs;
    for (const Tick& x : ticks) {
        grown.push_back(x);
    }

    std::cout << "loaded " << ticks.size() << ", rejected " << rejected << '\n';
    std::cout << "reserved: capacity " << ticks.capacity() << ", " << reserved << " allocation\n";
    std::cout << "grown: capacity " << grown.capacity() << ", " << g_allocs - start << " allocations\n";
    std::cout << "span " << (ticks.back().ts_ns - ticks.front().ts_ns) / 1000000 << " ms\n";
    return 0;
}

