            m2_ += (x - old) * (x - mean_ + old - old_mean);
        }
        ring_[head_] = x;
        head_ = (head_ + 1) % N;
    }
    bool full() const { return count_ == N; }
    double mean() const { return mean_; }
    double stdev() const { return std::sqrt(std::max(m2_, 0.0) / (count_ - 1)); }

