#include <cstdint>
#include <iomanip>
#include <iostream>

struct Tick {
    int64_t ts_ns;
    int64_t bid_ticks, ask_ticks;
    int64_t bid_sz, ask_sz;
};

// Long when the bid holds most of the size, short when the ask does, else flat.
struct Imbalance {
    double threshold;
    int operator()(const Tick& t) const {
        const double imb = double(t.bid_sz - t.ask_sz) / (t.bid_sz + t.ask_sz);
        return imb > threshold ? 1 : (imb < -threshold ? -1 : 0);
    }
};

struct Vwap {  // sum(price * qty) / sum(qty)
    int64_t qty = 0;
    int64_t notional = 0;
    void add(int64_t q, int64_t px) {
        qty += q;
        notional += q * px;
    }
    double value() const { return qty > 0 ? double(notional) / qty : 0.0; }
};

template <typename Signal>
class Strategy {
public:
    Strategy(Signal signal, int64_t lot) : signal_(signal), lot_(lot) {}

    void on_tick(const Tick& t) {
        const int64_t qty = signal_(t) * lot_ - position_;  // shares to trade
        if (qty > 0) {
            buys_.add(qty, t.ask_ticks);  // buy at the ask
        } else if (qty < 0) {
            sells_.add(-qty, t.bid_ticks);  // sell at the bid
        }
        position_ += qty;
        mark_ = position_ > 0 ? t.bid_ticks : t.ask_ticks;  // the price to get out
    }

    int64_t position() const { return position_; }
    int64_t pnl_ticks() const { return sells_.notional - buys_.notional + position_ * mark_; }
    const Vwap& buys() const { return buys_; }
    const Vwap& sells() const { return sells_; }

private:
    Signal signal_;
    int64_t lot_;
    int64_t position_ = 0;
    int64_t mark_ = 0;
    Vwap buys_, sells_;
};

int main() {
    int n = 0;
    std::cin >> n;
    Strategy<Imbalance> strategy(Imbalance{0.5}, 100);
    for (int i = 0; i < n; ++i) {
        Tick t{};
        std::cin >> t.ts_ns >> t.bid_ticks >> t.ask_ticks >> t.bid_sz >> t.ask_sz;
        strategy.on_tick(t);
    }
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "bought " << strategy.buys().qty << " at " << strategy.buys().value() / 100 << '\n';
    std::cout << "sold " << strategy.sells().qty << " at " << strategy.sells().value() / 100 << '\n';
    std::cout << std::setprecision(2);
    std::cout << "position " << strategy.position() << ", pnl " << strategy.pnl_ticks() / 100.0 << '\n';
    return 0;
}

