struct Tick {
    int64_t ts_ns;
    int64_t bid_ticks, ask_ticks;
    int64_t bid_sz, ask_sz;
};

// Long after the mid ticks up, short after it ticks down, flat when it holds.
struct Momentum {
    int64_t last_mid2 = 0;  // twice the mid, so it stays a whole number of ticks
    int operator()(const Tick& t) {
        const int64_t mid2 = t.bid_ticks + t.ask_ticks;
        int target = 0;
        if (last_mid2 != 0) {
            target = mid2 > last_mid2 ? 1 : (mid2 < last_mid2 ? -1 : 0);
