#include <vector>

struct Tick {
    int64_t ts_ns;
    int64_t bid_ticks, ask_ticks;
    int64_t bid_sz, ask_sz;
};

struct AlwaysLong {  // buy and hold: the baseline a strategy has to beat
    int operator()(const Tick&) const { return 1; }
};

template <typename Signal>
struct Strategy {  // the previous part's strategy, cut down to its P&L
    Strategy(Signal s, int64_t l) : signal(s), lot(l) {}
    void on_tick(const Tick& t) {
        const int64_t qty = signal(t) * lot - position;
        cash -= qty * (qty > 0 ? t.ask_ticks : t.bid_ticks);
        position += qty;
        mark = position > 0 ? t.bid_ticks : t.ask_ticks;
    }
    int64_t pnl_ticks() const { return cash + position * mark; }
    Signal signal;
    int64_t lot, position = 0, cash = 0, mark = 0;
