}

std::vector<Tick> drop_thin(std::vector<Tick> ticks, int64_t min_size) {  // stage 2
    auto thin = [&](const Tick& t) { return t.bid_sz < min_size || t.ask_sz < min_size; };
    ticks.erase(std::remove_if(ticks.begin(), ticks.end(), thin), ticks.end());
